const headers = { 'Authorization': 'Bearer <your-api-key>', 'Content-Type': 'application/json' };

const submitted = await fetch('https://my.neuronai.uz/api/v1/tts/jobs', {
    method: 'POST',
    headers: { ...headers, 'Idempotency-Key': crypto.randomUUID() },
    body: JSON.stringify({ voice_id: 'kamron', text: 'Assalomu alaykum! Bu NeuronAI matn-nutq xizmati orqali yaratilgan ovoz.', language: 'uz' }),
}).then((r) => r.json());

let job = submitted.data;
while (job.status === 'queued' || job.status === 'running') {
    await new Promise((resolve) => setTimeout(resolve, 2000));
    job = (await fetch(`https://my.neuronai.uz/api/v1/tts/jobs/${job.id}`, { headers }).then((r) => r.json())).data;
}

if (job.status === 'failed') throw new Error(job.error.message);

const audio = await fetch(job.audio_url, { headers }).then((r) => r.blob());

use Illuminate\Support\Facades\Http;
use Illuminate\Support\Str;

$api = Http::withHeaders(['Authorization' => 'Bearer <your-api-key>']);

$job = $api->withHeaders(['Idempotency-Key' => (string) Str::uuid()])
    ->post('https://my.neuronai.uz/api/v1/tts/jobs', ['voice_id' => 'kamron', 'text' => 'Assalomu alaykum! Bu NeuronAI matn-nutq xizmati orqali yaratilgan ovoz.', 'language' => 'uz'])
    ->json('data');

while (in_array($job['status'], ['queued', 'running'], true)) {
    sleep(2);
    $job = $api->get("https://my.neuronai.uz/api/v1/tts/jobs/{$job['id']}")->json('data');
}

if ($job['status'] === 'failed') {
