let cursor = null;
const voices = [];

do {
    const query = cursor ? `type=stock&cursor=${cursor}` : 'type=stock';
    const response = await fetch(`https://my.neuronai.uz/api/v1/tts/voices?${query}`);
    const { data, next_cursor: nextCursor } = await response.json();

